+    fn selection_spans(&self, focus: PaneFocus, row: usize, line: &str) -> Spans<'static> {
+        let Some((start, end)) = self.selection_range(focus, row, line.chars().count()) else {
+            return Spans::from(vec![Span::raw(line.to_string())]);
+        };
+        if start == end {
+            return Spans::from(vec![Span::raw(line.to_string())]);
+        }
+        Spans::from(vec![
+            Span::raw(char_slice(line, 0, start)),
+            Span::styled(
+                char_slice(line, start, end),
+                Style::default().add_modifier(Modifier::REVERSED),
+            ),
+            Span::raw(char_slice(line, end, line.chars().count())),
+        ])
+    }
+
+    fn selection_range(
+        &self,
+        focus: PaneFocus,
+        row: usize,
+        line_len: usize,
+    ) -> Option<(usize, usize)> {
+        let selection = self.visual_selection.as_ref()?;
+        if selection.focus != focus {
+            return None;
+        }
+        Self::selection_range_for(
+            selection.kind,
+            selection.anchor,
+            selection.cursor,
+            row,
+            line_len,
+        )
+    }

